<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {api,openProtected} from './api'
import './forum.css'
type Source={chunk_id:number;material_id:number;title:string;excerpt:string;current:boolean}
type Node={id:number;name:string;active:boolean;revision:number;metric:{mastery:string|null;band:string;sample_size:number;evidence?:any[];students_with_data?:number}}
type Edge={id:number;prerequisite_id:number;target_id:number;sources:Source[]}
type Graph={nodes:Node[];edges:Edge[];resources:any[];revision:number;learning_version:string;window:{start:string;end:string};include_unpublished:boolean}
type Proposal={nodes:{key:string;name:string;source_ids:number[];enabled?:boolean}[];edges:{from:string;to:string;source_ids:number[];enabled?:boolean}[]}
type Candidate={id:number;status:string;sources:Source[];proposal:any;reviewed_proposal:any;skill:string;model:string;error:string;review_reason:string}
const props=defineProps<{courseId:number;isTeacher:boolean}>()
const base=`courses/${props.courseId}/graph/`
const graph=ref<Graph|null>(null),candidates=ref<Candidate[]>([]),next=ref<number|null>(null),config=ref({extraction_enabled:true,revision:0}),materials=ref<{id:number;title:string}[]>([]),selectedMaterials=ref<number[]>([])
const busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),selected=ref<Node|null>(null),resources=ref<any>(null),editName=ref(''),editActive=ref(true),reason=ref(''),materialId=ref(''),drafts=ref<Record<number,Proposal>>({}),versions=ref<any[]>([])
const start=ref(new Date(Date.now()-90*86400000).toISOString().slice(0,10)),end=ref(new Date(Date.now()+86400000).toISOString().slice(0,10))
const labels:Record<string,string>={unknown:'未知',consolidate:'待巩固',developing:'发展中',secure:'较稳固'}
const statuses:Record<string,string>={running:'抽取中',awaiting_review:'待教师校对',approved:'已批准',rejected:'已拒绝',cancelled:'已取消',no_evidence:'无充分依据',failed:'失败'}
function name(id:number){return graph.value?.nodes.find(n=>n.id===id)?.name||'#'+id}
const diagram=computed(()=>{
 const nodes=graph.value?.nodes||[],edges=graph.value?.edges||[]
 const depth=new Map(nodes.map(n=>[n.id,0])),degree=new Map(nodes.map(n=>[n.id,0]))
 for(const e of edges)degree.set(e.target_id,(degree.get(e.target_id)||0)+1)
 const queue=nodes.filter(n=>!degree.get(n.id)).map(n=>n.id)
 for(let i=0;i<queue.length;i++)for(const e of edges.filter(e=>e.prerequisite_id===queue[i])){depth.set(e.target_id,Math.max(depth.get(e.target_id)||0,(depth.get(e.prerequisite_id)||0)+1));degree.set(e.target_id,(degree.get(e.target_id)||0)-1);if(!degree.get(e.target_id))queue.push(e.target_id)}
 const levels=new Map<number,number>(),positions=new Map<number,{x:number;y:number}>()
 for(const n of nodes){const d=depth.get(n.id)||0,slot=levels.get(d)||0;levels.set(d,slot+1);positions.set(n.id,{x:20+d*240,y:20+slot*100})}
 return {positions,width:Math.max(260,(Math.max(0,...depth.values())+1)*240),height:Math.max(120,...[...levels.values()].map(n=>n*100+20))}
})
function color(band:string){return ({secure:'#d6eee1',developing:'#fff0ce',consolidate:'#f8ded3'} as Record<string,string>)[band]||'#ebebeb'}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){try{graph.value=await api<Graph>(base+`?start=${encodeURIComponent(new Date(start.value+'T00:00:00Z').toISOString())}&end=${encodeURIComponent(new Date(end.value+'T00:00:00Z').toISOString())}`);if(selected.value)selected.value=graph.value.nodes.find(n=>n.id===selected.value!.id)||null;resources.value=null}catch(e){graph.value=null;selected.value=null;resources.value=null;throw e}}
async function loadCandidates(page=1){const data=await api<{items:Candidate[];next_page:number|null}>(base+`candidates/?page=${page}`);candidates.value=page===1?data.items:[...candidates.value,...data.items];next.value=data.next_page;for(const c of data.items)if(!drafts.value[c.id]&&c.proposal.nodes)drafts.value[c.id]={nodes:c.proposal.nodes.map((n:any)=>({...n,enabled:true})),edges:c.proposal.edges.map((e:any)=>({...e,enabled:true}))}}
async function refresh(){await load();if(props.isTeacher){config.value=await api(base+'config/');await loadCandidates()}}
async function toggle(){await run(async()=>{config.value=await api(base+'config/','PUT',{extraction_enabled:!config.value.extraction_enabled,expected_revision:config.value.revision});notice.value=config.value.extraction_enabled?'已启用抽取技能':'已停用抽取技能'})}
async function extract(){await run(async()=>{await api(base+'candidates/','POST',{material_ids:selectedMaterials.value});await loadCandidates();notice.value='候选已保存，正式图谱等待教师逐项校对批准'})}
async function review(c:Candidate,action:string){await run(async()=>{const draft=drafts.value[c.id];const included=new Set(draft?.nodes.filter(n=>n.enabled).map(n=>n.key));const proposal=action==='approve'?{nodes:draft.nodes.filter(n=>n.enabled).map(({enabled,...n})=>n),edges:draft.edges.filter(e=>e.enabled&&included.has(e.from)&&included.has(e.to)).map(({enabled,...e})=>e)}:undefined;await api(`graph/candidates/${c.id}/review/`,'POST',{action,reason:reason.value,expected_revision:graph.value!.revision,...(proposal?{proposal}:{})});await refresh();notice.value='审核结果已记录'})}
async function select(n:Node){await run(async()=>{selected.value=n;editName.value=n.name;editActive.value=n.active;resources.value=null;resources.value=await api(`graph/points/${n.id}/resources/`)})}
async function edit(){await run(async()=>{await api(`graph/points/${selected.value!.id}/`,'PUT',{name:editName.value,active:editActive.value,reason:reason.value,expected_revision:graph.value!.revision});selected.value=null;resources.value=null;await load();notice.value='已保留新图谱版本，历史试卷标签保持原快照'})}
async function link(){await run(async()=>{await api(base+'resources/','POST',{point_id:selected.value!.id,material_id:Number(materialId.value),reason:reason.value,expected_revision:graph.value!.revision});await load();resources.value=await api(`graph/points/${selected.value!.id}/resources/`);notice.value='课程资料已关联'})}
async function loadVersions(){await run(async()=>{versions.value=(await api<{items:any[]}>(base+'versions/')).items})}
onMounted(async()=>{await run(async()=>{await refresh();if(props.isTeacher)materials.value=await api(`courses/${props.courseId}/materials/`)});loading.value=false})
</script>
<template>
<section class="forum-workspace graph-workspace"><div class="section-head"><div><h2>知识图谱</h2><p>先修关系须有资料依据并经教师批准；颜色与学情分析使用同一正式评分口径。</p></div><button class="secondary" :disabled="busy" @click="run(refresh)">刷新图谱</button></div><p v-if="loading" role="status">正在加载图谱…</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<form class="forum-card graph-filters" @submit.prevent="run(load)"><label>开始日期（UTC）<input v-model="start" type="date" required></label><label>结束日期（UTC，不含当日）<input v-model="end" type="date" required></label><button class="secondary" :disabled="busy">应用窗口</button></form>
<template v-if="graph"><p>图谱版本 {{graph.revision}} · 评分数据版本 {{graph.learning_version.slice(0,16)}} · {{isTeacher?'班级有数据学生掌握度均值':'本人已公开正式评分'}}。无证据为未知，低于60%待巩固、60%–不足80%发展中、80%以上较稳固；不作为能力的绝对判断。</p><p v-if="!graph.nodes.length">尚无知识点，请教师创建标签或抽取候选。</p><div v-if="graph.nodes.length" class="graph-diagram"><svg :viewBox="`0 0 ${diagram.width} ${diagram.height}`" :style="{minWidth:Math.min(diagram.width,720)+'px'}" role="img" aria-label="已批准先修图，箭头由先修知识指向后学知识"><defs><marker id="graph-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#68796e"/></marker></defs><line v-for="e in graph.edges" :key="e.id" :x1="(diagram.positions.get(e.prerequisite_id)?.x||0)+190" :y1="(diagram.positions.get(e.prerequisite_id)?.y||0)+32" :x2="diagram.positions.get(e.target_id)?.x||0" :y2="(diagram.positions.get(e.target_id)?.y||0)+32" stroke="#68796e" stroke-width="2" marker-end="url(#graph-arrow)"/><g v-for="n in graph.nodes" :key="n.id" :transform="`translate(${diagram.positions.get(n.id)?.x},${diagram.positions.get(n.id)?.y})`"><title>{{n.name}} · {{labels[n.metric.band]}}</title><rect width="190" height="65" rx="9" :fill="color(n.metric.band)" stroke="#819086"/><text x="12" y="25" font-size="13">{{n.name.length>12?n.name.slice(0,12)+'…':n.name}}</text><text x="12" y="48" font-size="12" fill="#4a544d">{{labels[n.metric.band]}} · {{n.metric.sample_size}} 题</text></g></svg></div><div class="graph-nodes"><button v-for="n in graph.nodes" :key="n.id" class="graph-node" :data-band="n.metric.band" @click="select(n)"><strong>{{n.name}} {{n.active?'':'（已停用）'}}</strong><span>{{n.metric.mastery===null?'未知':(Number(n.metric.mastery)*100).toFixed(1)+'%'}} · {{labels[n.metric.band]}}</span><small>{{n.metric.sample_size}} 道有效题{{n.metric.students_with_data!==undefined?' · '+n.metric.students_with_data+'人有数据':''}}</small></button></div><h3>已批准的先修关系</h3><p v-if="!graph.edges.length">尚无先修关系；不会仅凭模型建议建立关系。</p><article v-for="e in graph.edges" :key="e.id" class="forum-card"><strong>{{name(e.prerequisite_id)}} → {{name(e.target_id)}}</strong><details><summary>关系出处</summary><p v-for="s in e.sources" :key="s.chunk_id">{{s.title}} · 片段 #{{s.chunk_id}} · {{s.current?'来源有效':'来源已变化，需教师复核'}}<br>{{s.excerpt}}</p></details></article>
<article v-if="selected" class="forum-card"><h3>{{selected.name}} · 稳定 ID #{{selected.id}}</h3><template v-if="resources"><h4>关联课程资料</h4><p v-if="!resources.materials.length">暂无关联资料。</p><p v-for="m in resources.materials" :key="m.id">{{m.title}} <button class="secondary" @click="openProtected(m.preview_url)">预览资料</button><small v-if="m.sources.some((s:Source)=>!s.current)"> 引用资料已变化</small></p><p v-if="resources.next_page">仅显示前20条资料，更多资料可从课程资料列表查看。</p><h4>相关帖子</h4><p v-for="p in resources.posts" :key="p.id">帖子 #{{p.id}} · {{p.title}}</p><p v-if="!resources.posts.length">暂无相关帖子。</p><template v-if="isTeacher"><h4>关联题库（仅教师）</h4><p v-for="q in resources.questions" :key="q.id">题 #{{q.id}} · {{q.body}}</p></template><template v-else><h4>本人未满分证据</h4><p v-for="e in resources.my_incomplete_answers" :key="e.attempt_id+'-'+e.question_id">答卷 #{{e.attempt_id}} · 题 #{{e.question_id}} · {{e.score}}/{{e.maximum}} · 评分 v{{e.grade_revision}}</p><p v-if="!resources.my_incomplete_answers.length">近90天无可见的未满分正式评分证据。</p></template></template>
<details v-if="selected.metric.evidence?.length"><summary>掌握度评分证据</summary><p v-for="e in selected.metric.evidence" :key="e.attempt_id+'-'+e.question_id">答卷 #{{e.attempt_id}} · 题 #{{e.question_id}} · {{e.score}}/{{e.maximum}} · 评分 v{{e.grade_revision}}</p></details>
<template v-if="isTeacher"><form class="forum-form" @submit.prevent="edit"><label>知识点名称<input v-model="editName" required maxlength="100"></label><label><input v-model="editActive" type="checkbox">启用（停用保留历史 ID）</label><label>修订理由<input v-model="reason" required maxlength="500"></label><button class="primary" :disabled="busy">保存新版本</button></form><form class="forum-form" @submit.prevent="link"><label>挂接课程资料<select v-model="materialId" required><option value="">请选择</option><option v-for="m in materials" :key="m.id" :value="String(m.id)">{{m.title}}</option></select></label><label>关联理由<input v-model="reason" required maxlength="500"></label><button class="secondary" :disabled="busy||!selected.active">关联资料</button></form></template></article>
</template>
<template v-if="isTeacher"><article class="forum-card"><h3>知识点抽取技能</h3><p>{{config.extraction_enabled?'已启用':'已停用'}} · knowledge-extraction@1.0.0</p><button class="secondary" :disabled="busy" @click="toggle">{{config.extraction_enabled?'停用抽取':'启用抽取'}}</button><form class="forum-form" @submit.prevent="extract"><fieldset><legend>选择本课程已索引资料</legend><label v-for="m in materials" :key="m.id"><input v-model="selectedMaterials" type="checkbox" :value="m.id">{{m.title}}</label></fieldset><button class="primary" :disabled="busy||!config.extraction_enabled||!selectedMaterials.length">生成带出处候选</button></form></article>
<h3>候选与审批记录</h3><label>本次审核理由<input v-model="reason" maxlength="500" placeholder="请说明校对结果及批准/拒绝原因"></label><p v-if="!candidates.length">暂无抽取记录。</p><article v-for="c in candidates" :key="c.id" class="forum-card"><h4>候选 #{{c.id}} · {{statuses[c.status]||c.status}}</h4><p>{{c.skill}} · {{c.model}} · {{c.error||c.review_reason}}</p><details><summary>回查候选资料依据</summary><p v-for="s in c.sources" :key="s.chunk_id">{{s.title}} · 片段 #{{s.chunk_id}} · {{s.current?'有效':'已变化'}}<br>{{s.excerpt}}</p></details><template v-if="c.status==='awaiting_review'"><p>逐项核对名称、资料出处和先修方向。取消勾选可排除无依据的节点或关系；只批准有资料支持的内容。</p><template v-if="drafts[c.id]"><fieldset v-for="n in drafts[c.id].nodes" :key="n.key"><legend>知识点候选</legend><label><input v-model="n.enabled" type="checkbox">纳入此知识点</label><label>校对名称<input v-model="n.name" maxlength="100"></label><p>支持此知识点的资料片段：</p><label v-for="source in c.sources" :key="source.chunk_id"><input v-model="n.source_ids" type="checkbox" :value="source.chunk_id">{{source.title}} · 片段 #{{source.chunk_id}}</label></fieldset><fieldset v-for="(e,index) in drafts[c.id].edges" :key="index"><legend>先修关系候选</legend><label><input v-model="e.enabled" type="checkbox">纳入此关系</label><label>先修知识点<select v-model="e.from"><option v-for="n in drafts[c.id].nodes.filter(n=>n.enabled)" :key="n.key" :value="n.key">{{n.name}}</option></select></label><label>后学知识点<select v-model="e.to"><option v-for="n in drafts[c.id].nodes.filter(n=>n.enabled)" :key="n.key" :value="n.key">{{n.name}}</option></select></label><label v-for="source in c.sources" :key="source.chunk_id"><input v-model="e.source_ids" type="checkbox" :value="source.chunk_id">{{source.title}} · 片段 #{{source.chunk_id}}</label></fieldset></template><div class="forum-actions"><button class="primary" :disabled="busy||!reason.trim()" @click="review(c,'approve')">确认批准入图谱</button><button class="secondary" :disabled="busy||!reason.trim()" @click="review(c,'reject')">拒绝候选</button></div></template><button v-if="c.status==='running'" class="secondary" :disabled="busy||!reason.trim()" @click="review(c,'cancel')">取消任务</button><details v-if="c.status==='approved'"><summary>已批准内容</summary><p v-for="n in c.reviewed_proposal.nodes||[]" :key="n.key">{{n.name}} · {{n.source_ids.length}} 项资料出处</p><p v-for="(e,i) in c.reviewed_proposal.edges||[]" :key="i">{{c.reviewed_proposal.nodes.find((n:any)=>n.key===e.from)?.name}} → {{c.reviewed_proposal.nodes.find((n:any)=>n.key===e.to)?.name}}</p></details></article><button v-if="next" class="secondary" :disabled="busy" @click="run(()=>loadCandidates(next!))">更多候选</button>
<button class="secondary" :disabled="busy" @click="loadVersions">查看图谱版本历史</button><p v-for="v in versions" :key="v.number">版本 {{v.number}} · {{v.reason}} · {{new Date(v.created_at).toLocaleString()}}</p></template>
</section>
</template>
<style scoped>.graph-diagram{overflow-x:auto;border:1px solid #eee;border-radius:8px;margin:1rem 0}.graph-diagram svg{width:100%;display:block;max-height:600px}.graph-nodes{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:.8rem}.graph-node{display:grid;gap:.6rem;text-align:left;background:#fafafa;border:1px solid #ddd;border-left:5px solid #999;border-radius:8px;padding:1rem;color:inherit;overflow-wrap:anywhere}.graph-node[data-band=secure]{border-left-color:#287d59}.graph-node[data-band=developing]{border-left-color:#b98018}.graph-node[data-band=consolidate]{border-left-color:#bc5f41}.graph-filters{display:flex;flex-wrap:wrap;gap:1rem;align-items:end}.graph-filters label{display:grid;gap:.5rem}.graph-workspace textarea{width:100%;box-sizing:border-box}.graph-workspace pre{white-space:pre-wrap;overflow-wrap:anywhere}.graph-workspace details p{white-space:pre-wrap;overflow-wrap:anywhere}</style>
